package com.materialplanner;

import com.materialplanner.items.ItemStore;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Outlines bank items the current plan needs you to withdraw.
 */
class BankHighlightOverlay extends WidgetItemOverlay
{
	private final ItemManager itemManager;
	private final MaterialPlannerConfig config;

	private volatile Set<String> neededNames = Collections.emptySet();
	/** item id → whether it's needed; reset whenever the needed set changes */
	private volatile Map<Integer, Boolean> matchCache = new ConcurrentHashMap<>();

	@Inject
	BankHighlightOverlay(ItemManager itemManager, MaterialPlannerConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;
		showOnBank();
	}

	/**
	 * @param names normalized item names to highlight
	 */
	void setNeeded(Set<String> names)
	{
		neededNames = names;
		matchCache = new ConcurrentHashMap<>();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.highlightBank() || neededNames.isEmpty())
		{
			return;
		}

		Boolean hit = matchCache.computeIfAbsent(itemId, id ->
		{
			int canonical = itemManager.canonicalize(id);
			String name = itemManager.getItemComposition(canonical).getName();
			return neededNames.contains(ItemStore.normalize(name));
		});
		if (!hit)
		{
			return;
		}

		Color color = config.highlightColor();
		Rectangle bounds = widgetItem.getCanvasBounds();
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), color);
		if (outline != null && bounds != null)
		{
			graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
		}
	}
}

package com.materialplanner;

public enum CostMode
{
	AUTO("Auto (ironman: coins only)"),
	GE_PRICES("GE prices + coins"),
	COINS_ONLY("Coins only"),
	OFF("Off");

	private final String label;

	CostMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.materialplanner;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(MaterialPlannerConfig.GROUP)
public interface MaterialPlannerConfig extends Config
{
	String GROUP = "materialplanner";

	@ConfigSection(name = "Planner", description = "How material lists are worked out", position = 0)
	String plannerSection = "planner";

	@ConfigSection(name = "Storage", description = "Which items count as available", position = 1)
	String storageSection = "storage";

	@ConfigSection(name = "Recipe data", description = "Where recipes come from", position = 2)
	String dataSection = "data";

	// --- Planner -------------------------------------------------------------------------------------

	@ConfigItem(
		keyName = "expandRecipes",
		name = "Expand sub-recipes",
		description = "When you're missing an ingredient that can be crafted, plan its ingredients too",
		position = 1,
		section = plannerSection
	)
	default boolean expandRecipes()
	{
		return true;
	}

	@ConfigItem(
		keyName = "costMode",
		name = "Show costs",
		description = "GE prices of what you're short, plus coins the plan needs (sawmill fees and similar). "
			+ "Auto shows coins only on ironman accounts.",
		position = 2,
		section = plannerSection
	)
	default CostMode costMode()
	{
		return CostMode.AUTO;
	}

	@ConfigItem(
		keyName = "levelCheck",
		name = "Check levels",
		description = "Flag recipes your skill levels are too low for",
		position = 3,
		section = plannerSection
	)
	default boolean levelCheck()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideUnmet",
		name = "Hide recipes above my level",
		description = "Leave recipes you can't make yet out of the search dropdown",
		position = 4,
		section = plannerSection
	)
	default boolean hideUnmet()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightBank",
		name = "Highlight in bank",
		description = "Outline items in the bank that your plan needs you to withdraw",
		position = 5,
		section = plannerSection
	)
	default boolean highlightBank()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Outline color for bank highlighting",
		position = 6,
		section = plannerSection
	)
	default Color highlightColor()
	{
		return new Color(255, 170, 0, 230);
	}

	// --- Storage -------------------------------------------------------------------------------------

	@ConfigItem(
		keyName = "countWorn",
		name = "Count equipped items",
		description = "Count items you are wearing as available materials",
		position = 1,
		section = storageSection
	)
	default boolean countWorn()
	{
		return true;
	}

	@ConfigItem(
		keyName = "countOtherStorage",
		name = "Count other storage",
		description = "Count the seed vault, cargo holds, tackle box, forestry and huntsman's kits, looting bag, seed box and group storage as available",
		position = 2,
		section = storageSection
	)
	default boolean countOtherStorage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "checkBankMenu",
		name = "'Check bank' menu option",
		description = "Adds a 'Check bank' option when right-clicking items in your inventory or on the ground",
		position = 3,
		section = storageSection
	)
	default boolean checkBankMenu()
	{
		return true;
	}

	// --- Recipe data ---------------------------------------------------------------------------------

	@ConfigItem(
		keyName = "wikiRecipes",
		name = "Download wiki data",
		description = "Download the full recipe list and shop stock from the OSRS Wiki. When off, only the built-in recipes are available.",
		position = 1,
		section = dataSection
	)
	default boolean wikiRecipes()
	{
		return true;
	}

	@Range(min = 1, max = 60)
	@ConfigItem(
		keyName = "refreshDays",
		name = "Recipe refresh (days)",
		description = "How often to re-download recipes and shops from the wiki",
		position = 2,
		section = dataSection
	)
	default int refreshDays()
	{
		return 7;
	}
}

