	}

	@Override
	public Boolean membersWorld()
	{
		return membersWorld;
	}

	@Override
	public boolean ironman()
	{
		return ironman;
	}

	@Override
	public List<String> unmetQuests(String requirementText)
	{
		if (requirementText == null || requirementText.isEmpty() || questStates.isEmpty())
		{
			return Collections.emptyList();
		}
		return unmetQuestCache.computeIfAbsent(requirementText, text ->
		{
			String lower = text.toLowerCase(Locale.ROOT);
			// "Partial completion of X" / "started X" only needs the quest begun
			boolean partial = lower.contains("partial") || lower.contains("started") || lower.contains("during");
			List<String> unmet = new ArrayList<>();
			for (Quest q : Quest.values())
			{
				String name = q.getName().toLowerCase(Locale.ROOT);
				if (!lower.contains(name))
				{
					continue;
				}
				QuestState s = questStates.get(name);
				boolean met = s == QuestState.FINISHED || (partial && s == QuestState.IN_PROGRESS);
				if (s != null && !met)
				{
					unmet.add(q.getName());
				}
			}
			return unmet;
		});
	}

	@Override
	public Boolean stackable(String itemName)
	{
		String key = ItemStore.normalize(itemName);
		Boolean known = stackables.get(key);
		if (known != null || !stackLookups.add(key))
		{
			return known;
		}
		// Not seen in any container yet: look the item up by name, then read its definition on the client thread
		int id = -1;
		for (ItemPrice p : itemManager.search(itemName))
		{
			if (p.getName().equalsIgnoreCase(itemName))
			{
				id = p.getId();
				break;
			}
		}
		if (id <= 0)
		{
			stackables.put(key, false);
			return false;
		}
		final int itemId = id;
		clientThread.invokeLater(() ->
		{
			stackables.put(key, itemManager.getItemComposition(itemId).isStackable());
			refreshPanelSettings();
		});
		return null;
	}

	@Override
	public CostMode effectiveCostMode()
	{
		CostMode mode = config.costMode();
		if (mode == CostMode.AUTO)
		{
			return ironman ? CostMode.COINS_ONLY : CostMode.GE_PRICES;
		}
		return mode;
	}

	@Override
	public void onPlanChanged(Set<String> bankNeeded)
	{
		bankOverlay.setNeeded(bankNeeded);
	}

	// --- "Check bank" menu option ----------------------------------------------------------------

	/**
	 * Adds "Check bank" next to Examine on inventory items and ground items.
	 */
	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.checkBankMenu())
		{
			return;
		}

		MenuEntry entry = event.getMenuEntry();
		if (!"Examine".equals(entry.getOption()))
		{
			return;
		}

		final int itemId;
		if (entry.getType() == MenuAction.EXAMINE_ITEM_GROUND)
		{
			itemId = entry.getIdentifier();
		}
		else if ((entry.getParam1() >>> 16) == InterfaceID.INVENTORY && entry.getItemId() > 0)
		{
			itemId = entry.getItemId();
		}
		else
		{
			return;
		}

		client.getMenu().createMenuEntry(-1)
			.setOption("Check bank")
			.setTarget(entry.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(e -> checkBank(itemId));
	}

	private void checkBank(int itemId)
	{
		int canonical = itemManager.canonicalize(itemId);
		String name = itemManager.getItemComposition(canonical).getName();

		String msg;
		if (!store.hasBankSnapshot())
		{
			msg = "Material Planner: no bank snapshot yet. Open your bank once to record it.";
		}
		else
		{
			Counts c = store.countById(canonical);
			NumberFormat nf = NumberFormat.getIntegerInstance();
			StringBuilder sb = new StringBuilder(name)
				.append(" - Bank: <col=ff9040>").append(nf.format(c.bank())).append("</col>")
				.append(", Inventory: ").append(nf.format(c.get(Location.INVENTORY)));
			for (Map.Entry<Location, Long> e : c.asMap().entrySet())
			{
				Location loc = e.getKey();
				if (loc != Location.BANK && loc != Location.INVENTORY)
				{
					sb.append(", ").append(store.label(loc)).append(": ").append(nf.format(e.getValue()));
				}
			}
			sb.append(" <col=7f7f7f>(bank as of ").append(MaterialPlannerPanel.ago(store.getBankTime())).append(")</col>");
			msg = sb.toString();
		}
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
	}
}

package com.materialplanner.items;

import java.util.EnumMap;
import java.util.Map;

/**
 * How many of one item are in each tracked location.
 */
public final class Counts
{
	private final EnumMap<Location, Long> byLocation = new EnumMap<>(Location.class);

	public void add(Location loc, long qty)
	{
		byLocation.merge(loc, qty, Long::sum);
	}

	public long get(Location loc)
	{
		return byLocation.getOrDefault(loc, 0L);
	}

	public Map<Location, Long> asMap()
	{
		return byLocation;
	}

	/**
	 * On you right now. Worn items only count when the user allows it.
	 */
	public long carried(boolean includeWorn)
	{
		long sum = 0;
		for (Map.Entry<Location, Long> e : byLocation.entrySet())
		{
			if (e.getKey().isCarried() && (includeWorn || e.getKey() != Location.WORN))
			{
				sum += e.getValue();
			}
		}
		return sum;
	}

	public long bank()
	{
		return get(Location.BANK);
	}

	public long other()
	{
		long sum = 0;
		for (Map.Entry<Location, Long> e : byLocation.entrySet())
		{
			if (e.getKey().isOtherStorage())
			{
				sum += e.getValue();
			}
		}
		return sum;
	}

	public long total(boolean includeWorn, boolean includeOther)
	{
		return carried(includeWorn) + bank() + (includeOther ? other() : 0);
	}
}

package com.materialplanner.items;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Last-seen contents of every tracked location. Storage snapshots are saved per account;
 * inventory, equipment and rune pouch are live only.
 */
@Slf4j
public class ItemStore
{
	private static final String GROUP = "materialplanner";
	private static final Type LIST_TYPE = new TypeToken<List<StoredItem>>()
	{
	}.getType();

	/**
	 * One stack summed across locations, for the "All storage" view.
	 */
	public static final class Aggregate
	{
		public final int id;
		public final String name;
		public final Counts counts = new Counts();

		Aggregate(int id, String name)
		{
			this.id = id;
			this.name = name;
		}
	}

	private final ConfigManager configManager;
	private final Gson gson;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	private static final String KEY_CARGO_NAMES = "cargoBoatNames";
	private static final Type NAMES_TYPE = new TypeToken<Map<String, String>>()
	{
	}.getType();
	private static final Location[] CARGO_SLOTS = {
		Location.CARGO_HOLD_1, Location.CARGO_HOLD_2, Location.CARGO_HOLD_3, Location.CARGO_HOLD_4, Location.CARGO_HOLD_5
	};

	private final EnumMap<Location, Map<Integer, StoredItem>> items = new EnumMap<>(Location.class);
	/** Cargo hold slot → boat name read from the cargo hold window title. */
	private final EnumMap<Location, String> cargoNames = new EnumMap<>(Location.class);
	private final EnumMap<Location, Long> times = new EnumMap<>(Location.class);

	public ItemStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public void addListener(Runnable r)
	{
		listeners.add(r);
	}

	private void fire()
	{
		listeners.forEach(Runnable::run);
	}

	// The bank keeps its original keys so snapshots from earlier versions still load
	private static String itemsKey(Location loc)
	{
		return loc == Location.BANK ? "bankSnapshot" : "snapshot." + loc.name();
	}

	private static String timeKey(Location loc)
	{
		return loc == Location.BANK ? "bankSnapshotTime" : "snapshotTime." + loc.name();
	}

	/**
	 * Load saved snapshots for the current RuneScape profile and forget live containers.
	 */
	public void loadProfile()
	{
		EnumMap<Location, Map<Integer, StoredItem>> loaded = new EnumMap<>(Location.class);
		EnumMap<Location, Long> loadedTimes = new EnumMap<>(Location.class);
		for (Location loc : Location.values())
		{
			if (!loc.isPersistent())
			{
				continue;
			}
			String json = configManager.getRSProfileConfiguration(GROUP, itemsKey(loc));
			if (json == null || json.isEmpty())
			{
				continue;
			}
			try
			{
				List<StoredItem> list = gson.fromJson(json, LIST_TYPE);
				Map<Integer, StoredItem> m = new LinkedHashMap<>();
				if (list != null)
				{
					for (StoredItem it : list)
					{
						m.put(it.getId(), it);
					}
				}
				loaded.put(loc, m);
				String t = configManager.getRSProfileConfiguration(GROUP, timeKey(loc));
				loadedTimes.put(loc, t == null ? 0L : Long.parseLong(t));
			}
			catch (JsonSyntaxException | NumberFormatException e)
			{
				log.warn("Could not read saved snapshot for {}", loc, e);
			}
		}
		EnumMap<Location, String> names = new EnumMap<>(Location.class);
		String namesJson = configManager.getRSProfileConfiguration(GROUP, KEY_CARGO_NAMES);
		if (namesJson != null && !namesJson.isEmpty())
		{
			try
			{
				Map<String, String> m = gson.fromJson(namesJson, NAMES_TYPE);
				if (m != null)
				{
					for (Map.Entry<String, String> e : m.entrySet())
					{
						names.put(Location.valueOf(e.getKey()), e.getValue());
					}
				}
			}
			catch (JsonSyntaxException | IllegalArgumentException e)
			{
				log.warn("Could not read cargo hold names", e);
			}
		}

		synchronized (this)
		{
			items.clear();
			times.clear();
			cargoNames.clear();
			items.putAll(loaded);
			times.putAll(loadedTimes);
			cargoNames.putAll(names);
		}
		fire();
	}

	/**
	 * The storage slot for a boat's cargo hold, assigned the first time that boat's hold is seen.
	 */
	public Location cargoSlotFor(String boatName)
	{
		Location slot = null;
		synchronized (this)
		{
			for (Location loc : CARGO_SLOTS)
			{
				if (boatName.equalsIgnoreCase(cargoNames.get(loc)))
				{
					return loc;
				}
			}
			for (Location loc : CARGO_SLOTS)
			{
				if (!cargoNames.containsKey(loc))
				{
					slot = loc;
					break;
				}
			}
			if (slot == null)
			{
				// More than five boats seen; reuse the last slot
				slot = CARGO_SLOTS[CARGO_SLOTS.length - 1];
			}
			cargoNames.put(slot, boatName);
		}
		Map<String, String> save = new HashMap<>();
		synchronized (this)
		{
			for (Map.Entry<Location, String> e : cargoNames.entrySet())
			{
				save.put(e.getKey().name(), e.getValue());
			}
		}
		configManager.setRSProfileConfiguration(GROUP, KEY_CARGO_NAMES, gson.toJson(save, NAMES_TYPE));
		return slot;
	}

	/**
	 * Display name, using the boat's name for cargo holds.
	 */
	public synchronized String label(Location loc)
	{
		String boat = cargoNames.get(loc);
		return boat == null ? loc.getLabel() : "Cargo hold: " + boat;
	}

	public synchronized String shortLabel(Location loc)
	{
		String boat = cargoNames.get(loc);
		return boat == null ? loc.getShortLabel() : boat;
	}

	public void update(Location location, List<StoredItem> list)
	{
		Map<Integer, StoredItem> map = new LinkedHashMap<>();
		for (StoredItem it : list)
		{
			StoredItem prev = map.get(it.getId());
			map.put(it.getId(), prev == null ? it
				: new StoredItem(it.getId(), it.getName(), prev.getQuantity() + it.getQuantity()));
		}

		long now = System.currentTimeMillis();
		synchronized (this)
		{
			items.put(location, map);
			times.put(location, now);
		}

		if (location.isPersistent())
		{
			configManager.setRSProfileConfiguration(GROUP, itemsKey(location), gson.toJson(new ArrayList<>(map.values())));
			configManager.setRSProfileConfiguration(GROUP, timeKey(location), String.valueOf(now));
		}
		fire();
	}

	/**
	 * Forget inventory, equipment and rune pouch (logout / account switch). Saved storage is kept.
	 */
	public void clearLive()
	{
		synchronized (this)
		{
			for (Location loc : Location.values())
			{
				if (!loc.isPersistent())
				{
					items.remove(loc);
					times.remove(loc);
				}
			}
		}
		fire();
	}

	public synchronized boolean hasSnapshot(Location loc)
	{
		return times.getOrDefault(loc, 0L) > 0;
	}

	public synchronized long getTime(Location loc)
	{
		return times.getOrDefault(loc, 0L);
	}

	public boolean hasBankSnapshot()
	{
		return hasSnapshot(Location.BANK);
	}

	public long getBankTime()
	{
		return getTime(Location.BANK);
	}

	public synchronized List<StoredItem> getItems(Location loc)
	{
		Map<Integer, StoredItem> m = items.get(loc);
		return m == null ? new ArrayList<>() : new ArrayList<>(m.values());
	}

	/**
	 * Persistent locations that have been recorded at least once.
	 */
	public synchronized List<Location> recordedStorage()
	{
		List<Location> out = new ArrayList<>();
		for (Location loc : Location.values())
		{
			if (loc.isPersistent() && times.getOrDefault(loc, 0L) > 0)
			{
				out.add(loc);
			}
		}
		return out;
	}

	/**
	 * Everything in saved storage (not on you), summed by item.
	 */
	public synchronized List<Aggregate> allStorage()
	{
		Map<Integer, Aggregate> out = new LinkedHashMap<>();
		for (Map.Entry<Location, Map<Integer, StoredItem>> e : items.entrySet())
		{
			if (!e.getKey().isPersistent())
			{
				continue;
			}
			for (StoredItem it : e.getValue().values())
			{
				out.computeIfAbsent(it.getId(), id -> new Aggregate(id, it.getName())).counts.add(e.getKey(), it.getQuantity());
			}
		}
		return new ArrayList<>(out.values());
	}

	public synchronized Counts countById(int canonicalId)
	{
		Counts c = new Counts();
		for (Map.Entry<Location, Map<Integer, StoredItem>> e : items.entrySet())
		{
			StoredItem it = e.getValue().get(canonicalId);
			if (it != null)
			{
				c.add(e.getKey(), it.getQuantity());
			}
		}
		return c;
	}

	/**
	 * Recipes reference materials by name, so count every stack whose name matches (case-insensitive).
	 */
	public synchronized Map<String, Counts> countsByName()
	{
		Map<String, Counts> out = new HashMap<>();
		for (Map.Entry<Location, Map<Integer, StoredItem>> e : items.entrySet())
		{
			for (StoredItem it : e.getValue().values())
			{
				out.computeIfAbsent(normalize(it.getName()), k -> new Counts()).add(e.getKey(), it.getQuantity());
			}
		}
		return out;
	}

	/**
	 * Find an item id for a name from anything we have seen. Used for icons of untradeable items.
	 */
	public synchronized int idForName(String name)
	{
		String n = normalize(name);
		for (Map<Integer, StoredItem> m : items.values())
		{
			for (StoredItem it : m.values())
			{
				if (normalize(it.getName()).equals(n))
				{
					return it.getId();
				}
			}
		}
		return -1;
	}

	public static String normalize(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
	}
}

package com.materialplanner.items;

/**
 * Every place the plugin tracks items. "Carried" locations count as already on you;
 * "persistent" ones are saved per account and survive restarts.
 */
public enum Location
{
	INVENTORY("Inventory", "Inv", true, false),
	WORN("Worn", "Worn", true, false),
	RUNE_POUCH("Rune pouch", "Pouch", true, false),
	BANK("Bank", "Bank", false, true),
	SEED_VAULT("Seed vault", "Vault", false, true),
	SEED_BOX("Seed box", "Seed box", false, true),
	LOOTING_BAG("Looting bag", "Loot bag", false, true),
	GROUP_STORAGE("Group storage", "Group", false, true),
	TACKLE_BOX("Tackle box", "Tackle box", false, true),
	FORESTRY_KIT("Forestry kit", "Forestry kit", false, true),
	HUNTSMANS_KIT("Huntsman's kit", "Huntsman's kit", false, true),
	CARGO_HOLD_1("Cargo hold (boat 1)", "Hold 1", false, true),
	CARGO_HOLD_2("Cargo hold (boat 2)", "Hold 2", false, true),
	CARGO_HOLD_3("Cargo hold (boat 3)", "Hold 3", false, true),
	CARGO_HOLD_4("Cargo hold (boat 4)", "Hold 4", false, true),
	CARGO_HOLD_5("Cargo hold (boat 5)", "Hold 5", false, true);

	private final String label;
	private final String shortLabel;
	private final boolean carried;
	private final boolean persistent;

	Location(String label, String shortLabel, boolean carried, boolean persistent)
	{
		this.label = label;
		this.shortLabel = shortLabel;
		this.carried = carried;
		this.persistent = persistent;
	}

	public String getLabel()
	{
		return label;
	}

	public String getShortLabel()
	{
		return shortLabel;
	}

	public boolean isCarried()
	{
		return carried;
	}

	public boolean isPersistent()
	{
		return persistent;
	}

	/**
	 * Storage that isn't the bank and isn't on you.
	 */
	public boolean isOtherStorage()
	{
		return !carried && this != BANK;
	}
}

package com.materialplanner.items;

/**
 * One stack of an item: canonical (un-noted) item id, its name at capture time, and quantity.
 */
public final class StoredItem
{
	private final int id;
	private final String name;
	private final long quantity;

	public StoredItem(int id, String name, long quantity)
	{
		this.id = id;
		this.name = name;
		this.quantity = quantity;
	}

	public int getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public long getQuantity()
	{
		return quantity;
	}
}

package com.materialplanner.recipes;

import com.materialplanner.items.Counts;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Turns "make these recipes" into a material tree.
 * <p>
 * For every material it first uses what you already own (on you, then bank, then other storage), and only
 * plans to craft what is still missing, recursing into that recipe's ingredients. Stock is shared across
 * the whole plan, so two recipes needing the same planks don't both count the same planks.
 * <p>
 * Pure logic with no RuneLite dependencies, so it can be tested on its own.
 */
public final class Planner
{
	/**
	 * Method override meaning "don't craft this, I'll get it another way".
	 */
	public static final String NO_MAKE = "-";

	private static final Set<String> NEVER_EXPAND = new HashSet<>(Collections.singletonList("coins"));

	public enum Status
	{
		/** Enough carried right now. */
		ON_YOU,
		/** Enough once withdrawn from bank or other storage. */
		IN_STORAGE,
		/** Some or all of it will be crafted; see children. */
		MAKE,
		/** Not enough and not craftable (or crafting disabled). */
		SHORT
	}

	public static final class Options
	{
		public boolean expand = true;
		public int maxDepth = 8;
		public boolean includeWorn = true;
		public boolean includeOther = true;
		/** normalized material name → recipe key to use, or NO_MAKE */
		public Map<String, String> methods = new HashMap<>();
		/** Whether an item stacks in one inventory slot, by display name. Null: only coins stack. */
		public java.util.function.Predicate<String> stackable;
	}

	/**
	 * A tool the plan needs at least once (not consumed). Any one of {@code alternatives} will do.
	 */
	public static final class ToolNeed
	{
		public final List<String> alternatives;
		/** Recipes that need it, for the tooltip. */
		public final List<String> usedBy = new ArrayList<>();

		ToolNeed(List<String> alternatives)
		{
			this.alternatives = alternatives;
		}

		public String label()
		{
			return String.join(" or ", alternatives);
		}
	}

	public static final class Node
	{
		public final String name;
		public final String key;
		public final long need;
		public final int depth;
		public long fromCarried;
		public long fromBank;
		public long fromOther;
		public long fromSurplus;
		public Recipe via;
		public long crafts;
		public long shortBy;
		public List<Recipe> alternatives = Collections.emptyList();
		public final List<Node> children = new ArrayList<>();

		Node(String name, long need, int depth)
		{
			this.name = name;
			this.key = normalize(name);
			this.need = need;
			this.depth = depth;
		}

		public long fromStock()
		{
			return fromCarried + fromBank + fromOther;
		}

		public Status status()
		{
			if (shortBy > 0)
			{
				return Status.SHORT;
			}
			if (via != null && crafts > 0)
			{
				return Status.MAKE;
			}
			if (fromBank + fromOther > 0)
			{
				return Status.IN_STORAGE;
			}
			return Status.ON_YOU;
		}

		public boolean subtreeShort()
		{
			if (shortBy > 0)
			{
				return true;
			}
			for (Node c : children)
			{
				if (c.subtreeShort())
				{
					return true;
				}
			}
			return false;
		}

		/**
		 * Stable id for remembering which rows the user collapsed.
		 */
		public String path(String parentPath)
		{
			return parentPath + "/" + key;
		}
	}

	public static final class Plan
	{
		public final List<Node> roots = new ArrayList<>();
		/** Raw materials still missing after crafting what can be crafted (display name → qty). */
		public final Map<String, Long> shortages = new LinkedHashMap<>();
		/** Items the plan takes from the bank, by normalized name. Drives bank highlighting. */
		public final Map<String, Long> fromBank = new HashMap<>();
		/** Items the plan takes from other storage, by normalized name. */
		public final Map<String, Long> fromOther = new HashMap<>();
		public long coinsNeeded;
		public long coinsAvailable;
		/** Every distinct tool the plan needs, in first-seen order. */
		public final List<ToolNeed> tools = new ArrayList<>();
		/** Inventory slots taken by materials you'll carry (stackables count once), plus tools. */
		public int inventorySlots;
		public int ready;
		public int toMake;
		public int shortCount;
	}

	private final Map<String, List<Recipe>> byOutput;
	private final Map<String, Counts> stock;
	private final Options opt;
	/** Remaining unallocated stock per item: [carried, bank, other]. */
	private final Map<String, long[]> remaining = new HashMap<>();
	/** Extra output from crafts that make more than needed (e.g. 15 arrows per action). */
	private final Map<String, Long> surplus = new HashMap<>();

	private Planner(Map<String, List<Recipe>> byOutput, Map<String, Counts> stock, Options opt)
	{
		this.byOutput = byOutput;
		this.stock = stock;
		this.opt = opt;
	}

	/**
	 * @param selections recipe → number of times it will be made, in display order
	 * @param byOutput   all recipes indexed by normalized output name
	 * @param stock      item counts indexed by normalized name
	 */
	public static Plan plan(Map<Recipe, Integer> selections, Map<String, List<Recipe>> byOutput,
		Map<String, Counts> stock, Options opt)
	{
		Planner p = new Planner(byOutput, stock, opt);
		Plan plan = new Plan();

		// Sum top-level needs first so shared materials are allocated once
		Map<String, Long> need = new LinkedHashMap<>();
		Map<String, String> display = new HashMap<>();
		Set<String> selectedOutputs = new HashSet<>();
		for (Map.Entry<Recipe, Integer> e : selections.entrySet())
		{
			selectedOutputs.add(normalize(e.getKey().name));
			for (Recipe.Material m : e.getKey().materials)
			{
				String k = normalize(m.name);
				need.merge(k, (long) m.quantity * e.getValue(), Long::sum);
				display.putIfAbsent(k, m.name);
			}
		}

		for (Map.Entry<String, Long> e : need.entrySet())
		{
			Node root = p.expand(display.get(e.getKey()), e.getValue(), 0, selectedOutputs);
			plan.roots.add(root);
			if (root.subtreeShort())
			{
				plan.shortCount++;
			}
			else if (containsMake(root))
			{
				plan.toMake++;
			}
			else
			{
				plan.ready++;
			}
		}

		Map<String, ToolNeed> tools = new LinkedHashMap<>();
		for (Recipe r : selections.keySet())
		{
			addTools(tools, r);
		}
		Map<String, Long> carry = new LinkedHashMap<>();
		for (Node r : plan.roots)
		{
			p.collect(r, plan);
			p.collectExtras(r, tools, carry);
		}
		plan.tools.addAll(tools.values());
		int slots = 0;
		for (Map.Entry<String, Long> e : carry.entrySet())
		{
			slots += p.isStackable(e.getKey()) ? 1 : (int) Math.min(Integer.MAX_VALUE, e.getValue());
		}
		plan.inventorySlots = slots + plan.tools.size();
		Counts coins = stock.get("coins");
		plan.coinsAvailable = coins == null ? 0 : coins.total(opt.includeWorn, opt.includeOther);
		return plan;
	}

	private Node expand(String name, long need, int depth, Set<String> ancestry)
	{
		Node n = new Node(name, need, depth);
		long left = need;

		long s = surplus.getOrDefault(n.key, 0L);
		if (s > 0)
		{
			n.fromSurplus = Math.min(s, left);
			surplus.put(n.key, s - n.fromSurplus);
			left -= n.fromSurplus;
		}

		long[] r = remaining.computeIfAbsent(n.key, this::initialStock);
		n.fromCarried = take(r, 0, left);
		left -= n.fromCarried;
		n.fromBank = take(r, 1, left);
		left -= n.fromBank;
		n.fromOther = take(r, 2, left);
		left -= n.fromOther;

		if (left <= 0)
		{
			return n;
		}

		List<Recipe> candidates = candidates(n.key, ancestry);
		n.alternatives = candidates;
		Recipe chosen = opt.expand && depth < opt.maxDepth && !NEVER_EXPAND.contains(n.key)
			? choose(n.key, candidates) : null;

		if (chosen == null)
		{
			n.shortBy = left;
			return n;
		}

		long out = Math.max(1, chosen.outputQuantity);
		long crafts = (left + out - 1) / out;
		long extra = crafts * out - left;
		if (extra > 0)
		{
			surplus.merge(n.key, extra, Long::sum);
		}
		n.via = chosen;
		n.crafts = crafts;

		Set<String> childAncestry = new HashSet<>(ancestry);
		childAncestry.add(n.key);
		for (Recipe.Material m : chosen.materials)
		{
			n.children.add(expand(m.name, m.quantity * crafts, depth + 1, childAncestry));
		}
		return n;
	}

	private long[] initialStock(String key)
	{
		Counts c = stock.get(key);
		if (c == null)
		{
			return new long[3];
		}
		return new long[]{c.carried(opt.includeWorn), c.bank(), opt.includeOther ? c.other() : 0};
	}

	private static long take(long[] pool, int idx, long want)
	{
		if (want <= 0)
		{
			return 0;
		}
		long t = Math.min(pool[idx], want);
		pool[idx] -= t;
		return t;
	}

	/**
	 * Recipes that produce this item without needing anything already being made higher up the tree.
	 */
	private List<Recipe> candidates(String key, Set<String> ancestry)
	{
		List<Recipe> all = byOutput.getOrDefault(key, Collections.emptyList());
		List<Recipe> out = new ArrayList<>();
		for (Recipe r : all)
		{
			boolean loops = false;
			for (Recipe.Material m : r.materials)
			{
				String mk = normalize(m.name);
				if (mk.equals(key) || ancestry.contains(mk))
				{
					loops = true;
					break;
				}
			}
			if (!loops)
			{
				out.add(r);
			}
		}
		out.sort(DEFAULT_ORDER);
		return out;
	}

	/**
	 * Preference when the user hasn't picked a method: plain crafting before spells, fewer distinct
	 * ingredients, then fewer ingredients per item made.
	 */
	static final Comparator<Recipe> DEFAULT_ORDER = Comparator
		.comparing((Recipe r) -> r.usesSkill("Magic"))
		.thenComparingInt(r -> r.materials.size())
		.thenComparingDouble(r -> (double) r.totalMaterialQuantity() / Math.max(1, r.outputQuantity))
		.thenComparing(r -> r.name == null ? "" : r.name);

	private Recipe choose(String key, List<Recipe> candidates)
	{
		String pick = opt.methods.get(key);
		if (NO_MAKE.equals(pick))
		{
			return null;
		}
		if (pick != null)
		{
			for (Recipe r : candidates)
			{
				if (r.key().equals(pick))
				{
					return r;
				}
			}
		}
		if (candidates.isEmpty())
		{
			return null;
		}
		// Prefer a method whose ingredients you can actually get: owned already, or craftable.
		// Otherwise rare unlocks (sawmill coupons, vouchers) win just for being short recipes.
		Recipe best = candidates.get(0);
		int bestMissing = unobtainable(best);
		for (Recipe r : candidates)
		{
			int m = unobtainable(r);
			if (m < bestMissing)
			{
				best = r;
				bestMissing = m;
			}
		}
		return best;
	}

	/**
	 * Ingredients of {@code r} you don't own any of and can't craft.
	 */
	private int unobtainable(Recipe r)
	{
		int missing = 0;
		for (Recipe.Material m : r.materials)
		{
			String k = normalize(m.name);
			Counts c = stock.get(k);
			boolean owned = c != null && c.total(opt.includeWorn, opt.includeOther) > 0;
			if (!owned && !byOutput.containsKey(k))
			{
				missing++;
			}
		}
		return missing;
	}

	private void collect(Node n, Plan plan)
	{
		if (n.fromBank > 0)
		{
			plan.fromBank.merge(n.key, n.fromBank, Long::sum);
		}
		if (n.fromOther > 0)
		{
			plan.fromOther.merge(n.key, n.fromOther, Long::sum);
		}
		if (n.shortBy > 0)
		{
			plan.shortages.merge(n.name, n.shortBy, Long::sum);
		}
		if (n.key.equals("coins"))
		{
			plan.coinsNeeded += n.need;
		}
		for (Node c : n.children)
		{
			collect(c, plan);
		}
	}

	private void collectExtras(Node n, Map<String, ToolNeed> tools, Map<String, Long> carry)
	{
		long taken = n.fromStock();
		if (taken > 0)
		{
			carry.merge(n.name, taken, Long::sum);
		}
		if (n.via != null)
		{
			addTools(tools, n.via);
		}
		for (Node c : n.children)
		{
			collectExtras(c, tools, carry);
		}
	}

	private static void addTools(Map<String, ToolNeed> tools, Recipe r)
	{
		if (r.toolReqs == null)
		{
			return;
		}
		for (List<String> alts : r.toolReqs)
		{
			String key = normalize(String.join("|", alts));
			ToolNeed t = tools.computeIfAbsent(key, k -> new ToolNeed(alts));
			if (!t.usedBy.contains(r.displayName()))
			{
				t.usedBy.add(r.displayName());
			}
		}
	}

	private boolean isStackable(String name)
	{
		if ("coins".equals(normalize(name)))
		{
			return true;
		}
		return opt.stackable != null && opt.stackable.test(name);
	}

	/**
	 * Inventories needed to carry {@code slots} items, 28 slots each.
	 */
	public static int inventories(int slots)
	{
		return slots <= 0 ? 0 : (slots + 27) / 28;
	}

	private static boolean containsMake(Node n)
	{
		if (n.status() == Status.MAKE)
		{
			return true;
		}
		for (Node c : n.children)
		{
			if (containsMake(c))
			{
				return true;
			}
		}
		return false;
	}

	public static String normalize(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
	}

	/**
	 * Index recipes by what they produce.
	 */
	public static Map<String, List<Recipe>> indexByOutput(List<Recipe> recipes)
	{
		Map<String, List<Recipe>> idx = new HashMap<>();
		for (Recipe r : recipes)
		{
			idx.computeIfAbsent(normalize(r.name), k -> new ArrayList<>()).add(r);
		}
		return idx;
	}
}

package com.materialplanner.recipes;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * A single way to make something: what it produces, what it needs, and which skills.
 * Field names are the on-disk cache / seed file format.
 */
public class Recipe
{
	public static class Material
	{
		public String name;
		public int quantity;

		public Material()
		{
		}

		public Material(String name, int quantity)
		{
			this.name = name;
			this.quantity = quantity;
		}
	}

	public static class SkillReq
	{
		public String name;
		public int level;
		/** XP gained per action, 0 when the wiki has none. */
		public double experience;

		public SkillReq()
		{
		}

		public SkillReq(String name, int level)
		{
			this.name = name;
			this.level = level;
		}

		public SkillReq(String name, int level, double experience)
		{
			this(name, level);
			this.experience = experience;
		}
	}

	public String name;
	public int outputQuantity = 1;
	public List<SkillReq> skills = new ArrayList<>();
	public List<Material> materials = new ArrayList<>();
	public String facility;
	/** Tools as shown to the player, e.g. "Saw, Hammer". */
	public String tools;
	/** Each required tool, as a list of acceptable alternatives. */
	public List<List<String>> toolReqs = new ArrayList<>();
	/** Quest or other unlock text from the wiki, or null. */
	public String quest;
	public boolean members;
	public String source;

	/**
	 * Display-only, set at load time (transient: not written to the cache).
	 * variant: e.g. "Sloop" when the wiki lists several same-named recipes.
	 * showMaterials: same-named recipes we couldn't label; show their materials so they can be told apart.
	 */
	public transient String variant;
	public transient boolean showMaterials;

	public String displayName()
	{
		return variant == null ? name : name + " (" + variant + ")";
	}

	public int totalMaterialQuantity()
	{
		int sum = 0;
		for (Material m : materials)
		{
			sum += m.quantity;
		}
		return sum;
	}

	public String materialsText()
	{
		StringBuilder sb = new StringBuilder();
		for (Material m : materials)
		{
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(m.name).append(" x").append(m.quantity);
		}
		return sb.toString();
	}

	/**
	 * Second line shown under the name in lists.
	 */
	public String subtitle()
	{
		return showMaterials ? materialsText() : requirementsText();
	}

	/**
	 * Stable identity used to persist the user's selections across restarts and data refreshes.
	 */
	public String key()
	{
		StringBuilder sb = new StringBuilder(name == null ? "" : name).append('|');
		if (facility != null)
		{
			sb.append(facility);
		}
		for (Material m : materials)
		{
			sb.append('|').append(m.name).append('x').append(m.quantity);
		}
		return sb.toString();
	}

	/**
	 * The skill this recipe trains, for level goals: the first skill that gives XP.
	 */
	public SkillReq xpSkill()
	{
		for (SkillReq s : skills)
		{
			if (s.experience > 0)
			{
				return s;
			}
		}
		return null;
	}

	public boolean usesSkill(String skill)
	{
		for (SkillReq s : skills)
		{
			if (s.name != null && s.name.equalsIgnoreCase(skill))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * One-line summary of requirements, e.g. "Sailing 50, Construction 26 · Shipyard".
	 */
	public String requirementsText()
	{
		StringBuilder sb = new StringBuilder();
		for (SkillReq s : skills)
		{
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(s.name);
			if (s.level > 0)
			{
				sb.append(' ').append(s.level);
			}
		}
		if (facility != null && !facility.isEmpty())
		{
			if (sb.length() > 0)
			{
				sb.append(" · ");
			}
			sb.append(facility);
		}
		return sb.toString();
	}

	@Override
	public String toString()
	{
		return outputQuantity > 1 ? displayName() + " (x" + outputQuantity + ")" : displayName();
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof Recipe && Objects.equals(key(), ((Recipe) o).key());
	}

	@Override
	public int hashCode()
	{
		return key().hashCode();
	}
}

package com.materialplanner.recipes;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
