/**
 * Supplies every known recipe. Sources, merged in order:
 * <ol>
 *   <li>Built-in seed recipes bundled with the plugin (always available, curated).</li>
 *   <li>The OSRS Wiki recipe database, downloaded and cached in the plugin's data directory.</li>
 * </ol>
 */
@Slf4j
public class RecipeRepository
{
	private static final String WIKI_API = "https://oldschool.runescape.wiki/api.php";
	private static final String USER_AGENT = "RuneLite Material Planner plugin (https://github.com/biggin215/material-planner)";
	private static final int PAGE_SIZE = 500;
	private static final int MAX_ROWS = 40_000;
	// v2: adds XP, cleaned tools/facilities, quest text and the real members flag
	private static final String CACHE_NAME = "recipes-v3.json";
	private static final String SHOP_CACHE_NAME = "shops-v3.json";
	/** Cache files written by earlier versions of the plugin. */
	private static final String[] OLD_CACHE_NAMES = {"recipes.json", "recipes-v2.json", "shops-v1.json", "shops-v2.json"};
	private static final int MAX_SHOP_ROWS = 60_000;
	private static final Type SHOP_LIST_TYPE = new TypeToken<List<ShopSource>>()
	{
	}.getType();
	private static final Type LIST_TYPE = new TypeToken<List<Recipe>>()
	{
	}.getType();

	/**
	 * Skills hidden from the skill filter: combat and spellcasting skills appear on the wiki mostly as
	 * level requirements or spell costs, not things you make. Their recipes are still searchable.
	 */
	private static final java.util.Set<String> HIDDEN_FILTER_SKILLS = new java.util.TreeSet<>(String.CASE_INSENSITIVE_ORDER);

	static
	{
		HIDDEN_FILTER_SKILLS.addAll(java.util.Arrays.asList(
			"Attack", "Strength", "Defence", "Ranged", "Magic", "Hitpoints", "Prayer"));
	}

	private static final java.util.regex.Pattern BOAT_SUFFIX = java.util.regex.Pattern.compile("\\s*\\((Raft|Skiff|Sloop)\\)$");

	private final Gson gson;
	private final OkHttpClient http;
	/** Plugin data directory, or null when it couldn't be opened (the cache is then skipped). */
	private final Filepath cacheDir;

	private volatile List<Recipe> recipes = Collections.emptyList();
	private volatile List<String> skills = Collections.emptyList();
	private volatile Map<String, List<Recipe>> byOutput = Collections.emptyMap();
	private volatile Map<String, List<ShopSource>> shops = Collections.emptyMap();
	private volatile int xpRecipeCount;
	private volatile String status = "Loading recipes…";

	/**
	 * @param cacheDir the plugin's data directory from {@code Plugin#getPluginDirectory()}, or null
	 */
	public RecipeRepository(Gson gson, OkHttpClient http, Filepath cacheDir)
	{
		this.gson = gson;
		this.http = http;
		this.cacheDir = cacheDir;
	}

	public List<Recipe> getRecipes()
	{
		return recipes;
	}

	/**
	 * All recipes indexed by normalized output name, for sub-recipe expansion.
	 */
	public Map<String, List<Recipe>> getByOutput()
	{
		return byOutput;
	}

	/**
	 * Shops selling an item, cheapest coin price first. Empty when unknown.
	 */
	public List<ShopSource> getShops(String itemName)
	{
		return shops.getOrDefault(Planner.normalize(itemName), Collections.emptyList());
	}

	/**
	 * How many recipes have XP data, which level goals rely on.
	 */
	public int getXpRecipeCount()
	{
		return xpRecipeCount;
	}

	public List<String> getSkills()
	{
		return skills;
	}

	public String getStatus()
	{
		return status;
	}

	/**
	 * Blocking; call off the client and Swing threads.
	 *
	 * @param useWiki      whether wiki data may be used at all
	 * @param refreshDays  re-download when the cache is older than this
	 * @param forceRefresh ignore cache age
	 */
	public void load(boolean useWiki, int refreshDays, boolean forceRefresh)
	{
		deleteOldCaches();
		List<Recipe> seed = loadSeed();
		List<Recipe> wiki = Collections.emptyList();
		String wikiStatus = null;

		if (useWiki)
		{
			List<Recipe> cached = readCache();
			boolean stale = cached == null || forceRefresh
				|| System.currentTimeMillis() - cacheModified() > TimeUnit.DAYS.toMillis(refreshDays);

			if (stale)
			{
				status = "Downloading recipes from the OSRS Wiki…";
				try
				{
					List<Recipe> fresh = fetchWiki();
					if (!fresh.isEmpty())
					{
						writeCache(fresh);
						cached = fresh;
					}
				}
				catch (IOException | RuntimeException e)
				{
					log.warn("Wiki recipe download failed", e);
					wikiStatus = cached == null
						? "Wiki download failed; built-in recipes only"
						: "Wiki download failed; using cached recipes";
				}
			}
			if (cached != null)
			{
				wiki = cached;
			}
			loadShops(stale);
		}

		// Built-in boat-part recipes are labelled per boat; drop the wiki's unlabelled copies of them
		java.util.Set<String> seedBaseNames = new java.util.HashSet<>();
		for (Recipe r : seed)
		{
			seedBaseNames.add(BOAT_SUFFIX.matcher(r.name).replaceFirst("").toLowerCase());
		}

		Map<String, Recipe> merged = new LinkedHashMap<>();
		for (Recipe r : seed)
		{
			merged.put(r.key(), r);
		}
		for (Recipe r : wiki)
		{
			if (!seedBaseNames.contains(r.name.toLowerCase()))
			{
				merged.putIfAbsent(r.key(), r);
			}
		}
		List<Recipe> all = new ArrayList<>(merged.values());
		labelDuplicates(all);
		all.sort((a, b) -> String.CASE_INSENSITIVE_ORDER.compare(a.name, b.name));

		TreeSet<String> skillSet = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		for (Recipe r : all)
		{
			for (Recipe.SkillReq s : r.skills)
			{
				if (!HIDDEN_FILTER_SKILLS.contains(s.name))
				{
					skillSet.add(s.name);
				}
			}
		}

		int withXp = 0;
		for (Recipe r : all)
		{
			if (r.xpSkill() != null)
			{
				withXp++;
			}
		}
		xpRecipeCount = withXp;
		byOutput = Planner.indexByOutput(all);
		recipes = Collections.unmodifiableList(all);
		skills = Collections.unmodifiableList(new ArrayList<>(skillSet));
		status = wikiStatus != null ? wikiStatus : String.format("%,d recipes", all.size());
	}

	/**
	 * The wiki lists raft/skiff/sloop versions of boat parts under one name. Three Sailing recipes
	 * sharing a name, each needing more materials than the last, are labelled Raft, Skiff, Sloop.
	 * Any other same-named recipes show their materials instead so they can be told apart.
	 */
	private static void labelDuplicates(List<Recipe> all)
	{
		Map<String, List<Recipe>> byName = new LinkedHashMap<>();
		for (Recipe r : all)
		{
			r.variant = null;
			r.showMaterials = false;
			byName.computeIfAbsent(r.name.toLowerCase(), k -> new ArrayList<>()).add(r);
		}
		String[] boats = {"Raft", "Skiff", "Sloop"};
		for (List<Recipe> group : byName.values())
		{
			if (group.size() < 2)
			{
				continue;
			}
			if (group.size() == 3 && group.stream().allMatch(r -> r.usesSkill("Sailing")))
			{
				List<Recipe> sorted = new ArrayList<>(group);
				sorted.sort(java.util.Comparator.comparingInt(Recipe::totalMaterialQuantity));
				if (sorted.get(0).totalMaterialQuantity() < sorted.get(1).totalMaterialQuantity()
					&& sorted.get(1).totalMaterialQuantity() < sorted.get(2).totalMaterialQuantity())
				{
					for (int i = 0; i < 3; i++)
					{
						sorted.get(i).variant = boats[i];
					}
					continue;
				}
			}
			group.forEach(r -> r.showMaterials = true);
		}
	}

	private List<Recipe> loadSeed()
	{
		try (InputStream in = RecipeRepository.class.getResourceAsStream("seed-recipes.json"))
		{
			if (in == null)
			{
				return Collections.emptyList();
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				List<Recipe> list = gson.fromJson(reader, LIST_TYPE);
				if (list == null)
				{
					return Collections.emptyList();
				}
				list.forEach(r -> r.source = "built-in");
				return list;
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not load built-in recipes", e);
			return Collections.emptyList();
		}
	}

	private void deleteOldCaches()
	{
		for (String name : OLD_CACHE_NAMES)
		{
			Filepath f = cacheFile(name);
			if (f == null)
			{
				continue;
			}
			try
			{
				f.deleteIfExists();
			}
			catch (IOException e)
			{
				log.debug("Couldn't remove old cache file {}", name, e);
			}
		}
	}

	private Filepath cacheFile()
	{
		return cacheFile(CACHE_NAME);
	}

	private Filepath cacheFile(String name)
	{
		return cacheDir == null ? null : cacheDir.join(name);
	}

	private long cacheModified()
	{
		Filepath f = cacheFile();
		try
		{
			return f != null && f.exists() ? f.getLastModifiedTime().toMillis() : 0;
		}
		catch (IOException e)
		{
			return 0;
		}
	}

	private List<Recipe> readCache()
	{
		Filepath f = cacheFile();
		if (f == null || !f.exists())
		{
			return null;
		}
		try (Reader reader = f.openBufferedReader())
		{
			return gson.fromJson(reader, LIST_TYPE);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Recipe cache unreadable, will re-download", e);
			return null;
		}
	}

	private void writeCache(List<Recipe> list)
	{
		writeJson(CACHE_NAME, list, LIST_TYPE);
	}

	private void writeJson(String name, Object value, Type type)
	{
		Filepath f = cacheFile(name);
		if (f == null)
		{
			return;
		}
		try
		{
			cacheDir.createDirectories();
			// Write to a temp file first so a crash mid-write can't leave a corrupt cache
			Filepath tmp = cacheDir.join(name + ".tmp");
			try (Writer w = tmp.openBufferedWriter())
			{
				gson.toJson(value, type, w);
			}
			tmp.moveTo(f, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			log.warn("Could not write {}", name, e);
		}
	}

	// --- shops -----------------------------------------------------------------------------------

	/**
	 * Shop data is a nice-to-have: any failure leaves shop info empty and never affects recipes.
	 */
	private void loadShops(boolean refresh)
	{
		List<ShopSource> list = null;
		Filepath f = cacheFile(SHOP_CACHE_NAME);
		if (!refresh && f != null && f.exists())
		{
			try (Reader reader = f.openBufferedReader())
			{
				list = gson.fromJson(reader, SHOP_LIST_TYPE);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Shop cache unreadable", e);
			}
		}
		if (list == null)
		{
			try
			{
				status = "Downloading shop data from the OSRS Wiki…";
				list = fetchShops();
				if (!list.isEmpty())
				{
					writeJson(SHOP_CACHE_NAME, list, SHOP_LIST_TYPE);
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Wiki shop download failed", e);
				return;
			}
		}
		shops = indexShops(list);
	}

	static Map<String, List<ShopSource>> indexShops(List<ShopSource> list)
	{
		Map<String, List<ShopSource>> idx = new java.util.HashMap<>();
		for (ShopSource s : list)
		{
			if (s.item != null && s.store != null)
			{
				idx.computeIfAbsent(Planner.normalize(s.item), k -> new ArrayList<>()).add(s);
			}
		}
		// Coin shops first, then cheapest
		java.util.Comparator<ShopSource> order = java.util.Comparator
			.comparing((ShopSource s) -> !s.isCoins())
			.thenComparingInt(s -> s.price < 0 ? Integer.MAX_VALUE : s.price);
		for (List<ShopSource> l : idx.values())
		{
			l.sort(order);
		}
		return idx;
	}

	private List<ShopSource> fetchShops() throws IOException
	{
		List<ShopSource> out = new ArrayList<>();
		for (int offset = 0; offset < MAX_SHOP_ROWS; offset += PAGE_SIZE)
		{
			String query = "bucket('storeline').select('sold_item','sold_by','store_sell_price','store_currency','store_stock')"
				+ ".limit(" + PAGE_SIZE + ").offset(" + offset + ").run()";
			JsonArray rows = queryBucket(query);
			for (JsonElement row : rows)
			{
				if (!row.isJsonObject())
				{
					continue;
				}
				JsonObject ro = row.getAsJsonObject();
				ShopSource s = new ShopSource();
				s.item = WikiText.clean(text(ro.get("sold_item")));
				s.store = WikiText.clean(text(ro.get("sold_by")));
				s.page = WikiText.linkTarget(text(ro.get("sold_by")));
				s.currency = WikiText.clean(text(ro.get("store_currency")));
				s.stock = WikiText.clean(text(ro.get("store_stock")));
				s.price = WikiRecipeParser.num(ro.get("store_sell_price"), -1);
				if (s.item != null && !s.item.isEmpty() && s.store != null && !s.store.isEmpty())
				{
					out.add(s);
				}
			}
			if (rows.size() < PAGE_SIZE)
			{
				break;
			}
		}
		try
		{
			addShopLocations(out);
		}
		catch (IOException | RuntimeException e)
		{
			// Prices still work without locations; access checks and "nearest" just stay off
			log.warn("Wiki shop location download failed", e);
		}
		return out;
	}

	private static final int LOCLINE_BATCH = 40;

	/**
	 * Adds where each shop is (infobox_shop) and its map spots (locline, for the shop page or its owner).
	 */
	private void addShopLocations(List<ShopSource> shops) throws IOException
	{
		Map<String, String[]> info = new java.util.HashMap<>();
		for (int offset = 0; offset < MAX_SHOP_ROWS; offset += PAGE_SIZE)
		{
			JsonArray rows = queryBucket("bucket('infobox_shop').select('page_name','location','owner','is_members_only')"
				+ ".limit(" + PAGE_SIZE + ").offset(" + offset + ").run()");
			for (JsonElement row : rows)
			{
				if (!row.isJsonObject())
				{
					continue;
				}
				JsonObject ro = row.getAsJsonObject();
				String page = WikiText.clean(text(ro.get("page_name")));
				if (page == null || page.isEmpty())
				{
					continue;
				}
				info.putIfAbsent(Planner.normalize(page), new String[]{
					WikiText.clean(text(ro.get("location"))),
					WikiText.linkTarget(text(ro.get("owner"))),
					String.valueOf(WikiRecipeParser.parseMembers(ro.get("is_members_only")))});
			}
			if (rows.size() < PAGE_SIZE)
			{
				break;
			}
		}

		// Map spots for every shop page and owner we'll need
		Set<String> names = new java.util.TreeSet<>();
		for (ShopSource s : shops)
		{
			names.add(s.pageName());
			String[] i = info.get(Planner.normalize(s.pageName()));
			if (i != null && i[1] != null && !i[1].isEmpty())
			{
				names.add(i[1]);
			}
		}
		Map<String, List<int[]>> spots = new java.util.HashMap<>();
		List<String> batch = new ArrayList<>();
		for (String n : names)
		{
			batch.add(n);
			if (batch.size() == LOCLINE_BATCH)
			{
				fetchSpots(batch, spots);
				batch.clear();
			}
		}
		if (!batch.isEmpty())
		{
			fetchSpots(batch, spots);
		}

		for (ShopSource s : shops)
		{
			String[] i = info.get(Planner.normalize(s.pageName()));
			if (i != null)
			{
				s.location = i[0];
				s.members = Boolean.parseBoolean(i[2]);
			}
			List<int[]> c = spots.get(Planner.normalize(s.pageName()));
			if ((c == null || c.isEmpty()) && i != null && i[1] != null)
			{
				c = spots.get(Planner.normalize(i[1]));
			}
			s.coords = c;
		}
	}

	private void fetchSpots(List<String> pages, Map<String, List<int[]>> into) throws IOException
	{
		StringBuilder where = new StringBuilder();
		for (String p : pages)
		{
			if (where.length() > 0)
			{
				where.append(',');
			}
			where.append("{'page_name','").append(WikiText.lua(p)).append("'}");
		}
		String filter = pages.size() == 1 ? where.toString() : "bucket.Or(" + where + ")";
		JsonArray rows = queryBucket("bucket('locline').select('page_name','coordinates','plane')"
			+ ".where(" + filter + ").limit(" + PAGE_SIZE + ").run()");
		for (JsonElement row : rows)
		{
			if (!row.isJsonObject())
			{
				continue;
			}
			JsonObject ro = row.getAsJsonObject();
			String page = text(ro.get("page_name"));
			if (page == null)
			{
				continue;
			}
			int plane = WikiRecipeParser.num(ro.get("plane"), 0);
			JsonElement coords = ro.get("coordinates");
			List<String> parts = new ArrayList<>();
			if (coords != null && coords.isJsonArray())
			{
				for (JsonElement e : coords.getAsJsonArray())
				{
					parts.add(e.isJsonPrimitive() ? e.getAsString() : e.toString());
				}
			}
			else if (coords != null && !coords.isJsonNull())
			{
				parts.add(coords.isJsonPrimitive() ? coords.getAsString() : coords.toString());
			}
			for (String part : parts)
			{
				for (int[] c : ShopAccess.parseCoordinates(part))
				{
					c[2] = plane;
					into.computeIfAbsent(Planner.normalize(page), k -> new ArrayList<>()).add(c);
				}
			}
		}
	}

	private static String text(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return null;
		}
		if (e.isJsonArray())
		{
			JsonArray a = e.getAsJsonArray();
			return a.size() == 0 ? null : text(a.get(0));
		}
		return e.isJsonPrimitive() ? e.getAsString() : null;
	}

	/**
	 * Page through the wiki's "recipe" bucket, which backs the wiki's own recipe and calculator tables.
	 */
	private List<Recipe> fetchWiki() throws IOException
	{
		List<Recipe> out = new ArrayList<>();
		for (int offset = 0; offset < MAX_ROWS; offset += PAGE_SIZE)
		{
			String query = "bucket('recipe').select('page_name','production_json','is_members_only')"
				+ ".limit(" + PAGE_SIZE + ").offset(" + offset + ").run()";
			JsonArray rows = queryBucket(query);

			for (JsonElement row : rows)
			{
				if (!row.isJsonObject())
				{
					continue;
				}
				JsonObject ro = row.getAsJsonObject();
				String page = text(ro.get("page_name"));
				Recipe r = WikiRecipeParser.parse(ro.get("production_json"), page, ro.get("is_members_only"));
				if (r != null)
				{
					out.add(r);
				}
			}

			status = String.format("Downloading recipes from the OSRS Wiki… %,d", out.size());
			if (rows.size() < PAGE_SIZE)
			{
				break;
			}
		}
		log.debug("Downloaded {} recipes from the wiki", out.size());
		return out;
	}

	private JsonArray queryBucket(String query) throws IOException
	{
		String url = WIKI_API + "?action=bucket&format=json&query="
			+ URLEncoder.encode(query, StandardCharsets.UTF_8.name());
		Request req = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
		try (Response resp = http.newCall(req).execute())
		{
			ResponseBody body = resp.body();
			if (!resp.isSuccessful() || body == null)
			{
				throw new IOException("Wiki API returned HTTP " + resp.code());
			}
			@SuppressWarnings("deprecation")
			JsonElement root = new JsonParser().parse(body.charStream());
			return extractRows(root);
		}
	}

	/**
	 * The bucket API returns {"bucket": [...]}; fall back to the first array found in case of minor format changes.
	 */
	private static JsonArray extractRows(JsonElement root)
	{
		if (root == null || !root.isJsonObject())
		{
			throw new IllegalStateException("Unexpected wiki response");
		}
		JsonObject o = root.getAsJsonObject();
		if (o.has("error"))
		{
			throw new IllegalStateException("Wiki API error: " + o.get("error"));
		}
		if (o.has("bucket") && o.get("bucket").isJsonArray())
		{
			return o.getAsJsonArray("bucket");
		}
		for (Map.Entry<String, JsonElement> e : o.entrySet())
		{
			if (e.getValue().isJsonArray())
			{
				return e.getValue().getAsJsonArray();
			}
		}
		throw new IllegalStateException("No recipe rows in wiki response");
	}
}

package com.materialplanner.recipes;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Works out whether a player can reach a shop and ranks the ones they can.
 *
 * The wiki's shop location text ("Prifddinas", "Keldagrim") is matched against a hand-kept list of areas
 * that sit behind a quest or a skill level. Unlisted places are assumed open.
 */
public final class ShopAccess
{
	/** What we know about the player; any value may be unknown. */
	public interface Player
	{
		/** null when unknown. */
		Boolean membersWorld();

		/** Quests named in the text that the player hasn't done (partial completion accepted where the text says so). */
		List<String> unmetQuests(String requirementText);

		/** Real level, or 0 or less when unknown. */
		int realLevel(String skill);

		/** {x, y, plane} or null when not logged in. */
		int[] location();
	}

	private static final class Rule
	{
		final String[] places;
		final String quest;
		final String skill;
		final int level;

		Rule(String quest, String skill, int level, String... places)
		{
			this.places = places;
			this.quest = quest;
			this.skill = skill;
			this.level = level;
		}
	}

	/**
	 * Quest names follow RuneLite's quest list. "partial" means starting the quest is enough to get in.
	 */
	private static final List<Rule> RULES = java.util.Arrays.asList(
		new Rule("Song of the Elves", null, 0, "prifddinas"),
		new Rule("Partial completion of Mourning's End Part I", null, 0, "lletya"),
		new Rule("Underground Pass", null, 0, "tirannwn", "isafdar", "elf camp", "lletya", "prifddinas"),
		new Rule("Lost City", null, 0, "zanaris"),
		new Rule("Partial completion of The Giant Dwarf", null, 0, "keldagrim"),
		new Rule("Monkey Madness I", null, 0, "ape atoll", "marim"),
		new Rule("Cabin Fever", null, 0, "mos le'harmless"),
		new Rule("Lunar Diplomacy", null, 0, "lunar isle"),
		new Rule("Partial completion of The Fremennik Isles", null, 0, "neitiznot", "jatizso"),
		new Rule("Partial completion of Throne of Miscellania", null, 0, "miscellania", "etceteria"),
		new Rule("The Fremennik Trials", null, 0, "rellekka", "waterbirth"),
		new Rule("Priest in Peril", null, 0, "morytania", "canifis", "port phasmatys", "mort'ton", "burgh de rott",
			"darkmeyer", "meiyerditch", "slepe"),
		new Rule("Partial completion of In Aid of the Myreque", null, 0, "burgh de rott"),
		new Rule("Sins of the Father", null, 0, "darkmeyer", "slepe"),
		new Rule("Partial completion of Icthlarin's Little Helper", null, 0, "sophanem"),
		new Rule("Bone Voyage", null, 0, "fossil island"),
		new Rule("Shilo Village", null, 0, "shilo village"),
		new Rule("Death to the Dorgeshuun", null, 0, "dorgesh-kaan"),
		new Rule("Dragon Slayer II", null, 0, "myths' guild"),
		new Rule("Heroes' Quest", null, 0, "heroes' guild"),
		new Rule("Legends' Quest", null, 0, "legends' guild"),
		new Rule(null, "Crafting", 40, "crafting guild"),
		new Rule(null, "Cooking", 32, "cooks' guild", "cooking guild"),
		new Rule(null, "Fishing", 68, "fishing guild"),
		new Rule(null, "Mining", 60, "mining guild"),
		new Rule(null, "Woodcutting", 60, "woodcutting guild"),
		new Rule(null, "Farming", 45, "farming guild"),
		new Rule(null, "Ranged", 40, "ranging guild"),
		new Rule(null, "Hunter", 46, "hunter guild", "hunters' guild")
	);

	private ShopAccess()
	{
	}

	/**
	 * Why the player can't use this shop, or an empty list when nothing is known to stop them.
	 */
	public static List<String> blockers(ShopSource s, Player p)
	{
		Set<String> out = new LinkedHashSet<>();
		if (s.members && Boolean.FALSE.equals(p.membersWorld()))
		{
			out.add("members");
		}
		String where = ((s.location == null ? "" : s.location) + " " + (s.store == null ? "" : s.store))
			.toLowerCase(Locale.ROOT);
		for (Rule r : RULES)
		{
			if (!mentions(where, r.places))
			{
				continue;
			}
			if (r.quest != null)
			{
				out.addAll(p.unmetQuests(r.quest));
			}
			if (r.skill != null)
			{
				int lvl = p.realLevel(r.skill);
				if (lvl > 0 && lvl < r.level)
				{
					out.add(r.level + " " + r.skill);
				}
			}
		}
		return new ArrayList<>(out);
	}

	private static boolean mentions(String where, String[] places)
	{
		for (String place : places)
		{
			if (where.contains(place))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Approximate tiles between the player and the shop's nearest known spot, or -1 when either is unknown.
	 * Underground areas sit 6400 tiles north of the surface they're under, so they're folded back first.
	 */
	public static int distance(ShopSource s, int[] player)
	{
		if (player == null)
		{
			return -1;
		}
		List<int[]> spots = s.coords;
		if (spots == null || spots.isEmpty())
		{
			// Most single-spawn shopkeepers have no map spots on the wiki; use the town instead
			int[] town = ShopPlaces.find(s.location, s.store);
			if (town == null)
			{
				return -1;
			}
			spots = java.util.Collections.singletonList(town);
		}
		int best = -1;
		for (int[] c : spots)
		{
			if (c == null || c.length < 2)
			{
				continue;
			}
			int d = Math.max(Math.abs(c[0] - player[0]), Math.abs(surfaceY(c[1]) - surfaceY(player[1])));
			if (best < 0 || d < best)
			{
				best = d;
			}
		}
		return best;
	}

	private static int surfaceY(int y)
	{
		return y >= 6400 ? y - 6400 : y;
	}

	/** The shops worth showing for an item. */
	public static final class Pick
	{
		/** Cheapest reachable coin shop, nearest first among equal prices; null when none. */
		public ShopSource cheapest;
		/** Nearest reachable coin shop when it isn't the cheapest one; otherwise null. */
		public ShopSource nearest;
		/** Shops that sell it but can't be used yet, each with the reason. */
		public final List<String> locked = new ArrayList<>();
	}

	public static Pick pick(List<ShopSource> shops, Player p)
	{
		Pick pick = new Pick();
		int[] here = p.location();
		List<ShopSource> open = new ArrayList<>();
		for (ShopSource s : shops)
		{
			if (!s.isCoins() || s.price < 0)
			{
				continue;
			}
			List<String> why = blockers(s, p);
			if (why.isEmpty())
			{
				open.add(s);
			}
			else
			{
				pick.locked.add(s.store + " (needs " + String.join(", ", why) + ")");
			}
		}
		if (open.isEmpty())
		{
			return pick;
		}
		Comparator<ShopSource> byDistance = Comparator.comparingInt(s ->
		{
			int d = distance(s, here);
			return d < 0 ? Integer.MAX_VALUE : d;
		});
		open.sort(Comparator.comparingInt((ShopSource s) -> s.price).thenComparing(byDistance));
		pick.cheapest = open.get(0);
		ShopSource near = open.stream().min(byDistance).orElse(null);
		if (near != null && near != pick.cheapest && distance(near, here) >= 0)
		{
			pick.nearest = near;
		}
		return pick;
	}

	/**
	 * Pulls coordinates out of wiki location text: "x:3210,y:3424" pairs, or bare "3210,3424" pairs.
	 */
	public static List<int[]> parseCoordinates(String raw)
	{
		List<int[]> out = new ArrayList<>();
		if (raw == null)
		{
			return out;
		}
		java.util.regex.Matcher kv = java.util.regex.Pattern.compile("x\\s*[:=]\\s*(\\d{3,5})\\s*,\\s*y\\s*[:=]\\s*(\\d{3,5})")
			.matcher(raw);
		while (kv.find())
		{
			out.add(new int[]{Integer.parseInt(kv.group(1)), Integer.parseInt(kv.group(2)), 0});
		}
		if (out.isEmpty())
		{
			java.util.regex.Matcher bare = java.util.regex.Pattern.compile("(?<![\\d.])(\\d{3,5})\\s*,\\s*(\\d{3,5})(?![\\d.])")
				.matcher(raw);
			while (bare.find())
			{
				out.add(new int[]{Integer.parseInt(bare.group(1)), Integer.parseInt(bare.group(2)), 0});
			}
		}
		return out;
	}
}

