	/** Longest names first, so "east ardougne" wins over "ardougne". */
	private static final List<String> BY_LENGTH = new ArrayList<>(PLACES.keySet());

	static
	{
		BY_LENGTH.sort(Comparator.comparingInt(String::length).reversed());
	}

	private ShopPlaces()
	{
	}

	/**
	 * The rough position of the first known place named in the texts (checked in order), or null.
	 */
	static int[] find(String... texts)
	{
		for (String text : texts)
		{
			if (text == null || text.isEmpty())
			{
				continue;
			}
			String lower = text.toLowerCase(Locale.ROOT);
			for (String place : BY_LENGTH)
			{
				if (lower.contains(place))
				{
					return PLACES.get(place);
				}
			}
		}
		return null;
	}
}

package com.materialplanner.recipes;

/**
 * One shop that sells an item, from the wiki's storeline data.
 */
public class ShopSource
{
	public String item;
	public String store;
	/** The shop's wiki page when it differs from the shown name; may be null. */
	public String page;
	/** Price the shop charges, or -1 when unknown. */
	public int price = -1;
	/** "Coins" unless the shop uses another currency (tokkul, marks of grace...). */
	public String currency;
	/** Base stock as listed on the wiki, e.g. "10" or "∞"; may be null. */
	public String stock;
	/** Wiki location text, e.g. "Prifddinas, Tirannwn"; may be null. */
	public String location;
	public boolean members;
	/** Known spots for the shop or its owner as {x, y, plane}; may be null or empty. */
	public java.util.List<int[]> coords;

	public String pageName()
	{
		return page == null || page.isEmpty() ? store : page;
	}

	public boolean isCoins()
	{
		return currency == null || currency.isEmpty() || currency.equalsIgnoreCase("coins");
	}
}

package com.materialplanner.recipes;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Converts one row of the OSRS Wiki "recipe" bucket (its production_json field) into a {@link Recipe}.
 * <p>
 * The wiki's format is loosely typed (numbers are often strings, single values are sometimes not
 * wrapped in arrays), so every field is read defensively and anything unexpected is skipped.
 */
final class WikiRecipeParser
{
	private static final Pattern LEADING_INT = Pattern.compile("(\\d[\\d,]*)");

	private WikiRecipeParser()
	{
	}

	static Recipe parse(JsonElement productionJson, String pageName)
	{
		return parse(productionJson, pageName, null);
	}

	/**
	 * @param membersField the row's is_members_only value, which is more reliable than the JSON's own flag
	 */
	static Recipe parse(JsonElement productionJson, String pageName, JsonElement membersField)
	{
		JsonObject o = asObject(productionJson);
		if (o == null)
		{
			return null;
		}

		Recipe r = new Recipe();
		r.source = "wiki";

		JsonObject output = asObject(o.get("output"));
		if (output != null)
		{
			r.name = str(output.get("name"));
			r.outputQuantity = Math.max(1, num(output.get("quantity"), 1));
		}
		if (r.name == null || r.name.isEmpty())
		{
			r.name = pageName;
		}
		if (r.name == null || r.name.isEmpty())
		{
			return null;
		}
		// Wiki page names can carry a variant suffix after '#'
		r.name = r.name.replace('#', ' ').trim();

		for (JsonElement m : asArray(o.get("materials")))
		{
			JsonObject mo = asObject(m);
			if (mo == null)
			{
				continue;
			}
			String name = str(mo.get("name"));
			if (name == null || name.isEmpty())
			{
				continue;
			}
			r.materials.add(new Recipe.Material(name, Math.max(1, num(mo.get("quantity"), 1))));
		}
		if (r.materials.isEmpty())
		{
			// Nothing to plan for (e.g. pure gathering actions)
			return null;
		}

		for (JsonElement s : asArray(o.get("skills")))
		{
			JsonObject so = asObject(s);
			if (so == null)
			{
				continue;
			}
			String name = str(so.get("name"));
			if (name != null && !name.isEmpty())
			{
				double xp = firstNumber(so, "experience", "exp", "xp");
				r.skills.add(new Recipe.SkillReq(capitalize(WikiText.clean(name)), num(so.get("level"), 0), xp));
			}
		}

		String facility = WikiText.clean(joinish(firstPresent(o, "facilities", "facility")));
		r.facility = facility == null || facility.isEmpty() ? null : facility;

		String rawTools = joinish(o.get("tools"));
		r.toolReqs = WikiText.toolRequirements(rawTools);
		StringBuilder tools = new StringBuilder();
		for (java.util.List<String> alts : r.toolReqs)
		{
			if (tools.length() > 0)
			{
				tools.append(", ");
			}
			tools.append(String.join(" or ", alts));
		}
		r.tools = tools.length() == 0 ? null : tools.toString();

		String quest = WikiText.clean(joinish(firstPresent(o, "quest", "quests", "notes")));
		r.quest = quest == null || quest.isEmpty() ? null : quest;

		r.members = parseMembers(membersField != null ? membersField : o.get("members"));
		return r;
	}

	/**
	 * The wiki API sends a true yes/no field as an empty string and leaves a false one out; older or
	 * hand-written values may be "Yes"/"No", true/false or 1/0.
	 */
	static boolean parseMembers(JsonElement e)
	{
		String s = str(e);
		if (s == null)
		{
			// The wiki API leaves false yes/no fields out of the response entirely
			return false;
		}
		s = s.trim().toLowerCase();
		return !(s.equals("no") || s.equals("false") || s.equals("0") || s.equals("f2p"));
	}

	private static JsonElement firstPresent(JsonObject o, String... keys)
	{
		for (String k : keys)
		{
			JsonElement e = o.get(k);
			if (e != null && !e.isJsonNull())
			{
				return e;
			}
		}
		return null;
	}

	private static final Pattern DECIMAL = Pattern.compile("(\\d[\\d,]*(?:\\.\\d+)?)");

	static double firstNumber(JsonObject o, String... keys)
	{
		for (String k : keys)
		{
			String s = str(o.get(k));
			if (s == null)
			{
				continue;
			}
			Matcher m = DECIMAL.matcher(s);
			if (m.find())
			{
				try
				{
					return Double.parseDouble(m.group(1).replace(",", ""));
				}
				catch (NumberFormatException ignored)
				{
				}
			}
		}
		return 0;
	}

	private static JsonObject asObject(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return null;
		}
		if (e.isJsonObject())
		{
			return e.getAsJsonObject();
		}
		if (e.isJsonPrimitive() && e.getAsJsonPrimitive().isString())
		{
			try
			{
				// RuneLite ships Gson 2.8.5, which predates the static JsonParser.parseString
				@SuppressWarnings("deprecation")
				JsonElement p = new JsonParser().parse(e.getAsString());
				return p.isJsonObject() ? p.getAsJsonObject() : null;
			}
			catch (RuntimeException ex)
			{
				return null;
			}
		}
		return null;
	}

	private static JsonArray asArray(JsonElement e)
	{
		JsonArray a = new JsonArray();
		if (e == null || e.isJsonNull())
		{
			return a;
		}
		if (e.isJsonArray())
		{
			return e.getAsJsonArray();
		}
		a.add(e);
		return a;
	}

	private static String str(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return null;
		}
		if (e.isJsonPrimitive())
		{
			return e.getAsString().trim();
		}
		return null;
	}

	private static String joinish(JsonElement e)
	{
		StringBuilder sb = new StringBuilder();
		for (JsonElement x : asArray(e))
		{
			String s = str(x);
			if (s != null && !s.isEmpty())
			{
				if (sb.length() > 0)
				{
					sb.append(", ");
				}
				sb.append(s);
			}
		}
		return sb.length() == 0 ? null : sb.toString();
	}

	static int num(JsonElement e, int def)
	{
		String s = str(e);
		if (s == null)
		{
			return def;
		}
		Matcher m = LEADING_INT.matcher(s);
		if (!m.find())
		{
			return def;
		}
		try
		{
			return Integer.parseInt(m.group(1).replace(",", ""));
		}
		catch (NumberFormatException ex)
		{
			return def;
		}
	}

	private static String capitalize(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.materialplanner.recipes;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Turns wiki markup that leaks into bucket fields into plain text, e.g.
 * {@code <span class="plink-template">[[File:Fishing rod.png|link=Fishing rod]]</span>[[Fishing rod|Fishing rod]]}
 * becomes {@code Fishing rod}.
 */
public final class WikiText
{
	private static final Pattern FILE_LINK = Pattern.compile("\\[\\[(?:File|Image):[^\\]]*\\]\\]", Pattern.CASE_INSENSITIVE);
	private static final Pattern PIPED_LINK = Pattern.compile("\\[\\[[^\\]|]*\\|([^\\]]*)\\]\\]");
	private static final Pattern PLAIN_LINK = Pattern.compile("\\[\\[([^\\]]*)\\]\\]");
	private static final Pattern TEMPLATE = Pattern.compile("\\{\\{[^}]*\\}\\}");
	private static final Pattern HTML_TAG = Pattern.compile("<[^>]+>");
	private static final Pattern REF = Pattern.compile("<ref[^>]*>.*?</ref>|<ref[^>]*/>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
	private static final Pattern SPACES = Pattern.compile("\\s+");
	private static final Pattern OR_SPLIT = Pattern.compile("\\s+or\\s+|\\s*/\\s*", Pattern.CASE_INSENSITIVE);
	private static final Pattern OPTIONAL = Pattern.compile("\\(\\s*optional\\s*\\)", Pattern.CASE_INSENSITIVE);

	private WikiText()
	{
	}

	public static String clean(String s)
	{
		if (s == null)
		{
			return null;
		}
		String t = REF.matcher(s).replaceAll("");
		t = FILE_LINK.matcher(t).replaceAll("");
		t = replaceGroup(PIPED_LINK, t);
		t = replaceGroup(PLAIN_LINK, t);
		t = TEMPLATE.matcher(t).replaceAll("");
		t = HTML_TAG.matcher(t).replaceAll("");
		t = t.replace("&nbsp;", " ").replace("&amp;", "&").replace("&#39;", "'").replace("&quot;", "\"");
		t = t.replace("'''", "").replace("''", "");
		return SPACES.matcher(t).replaceAll(" ").trim();
	}

	private static String replaceGroup(Pattern p, String s)
	{
		Matcher m = p.matcher(s);
		StringBuffer sb = new StringBuffer();
		while (m.find())
		{
			m.appendReplacement(sb, Matcher.quoteReplacement(m.group(1)));
		}
		m.appendTail(sb);
		return sb.toString();
	}

	/**
	 * Parses a tools field like "Saw, Hammer" or "Butterfly net or Magic butterfly net" into requirements,
	 * each a list of acceptable alternatives. Optional tools and "None" are dropped.
	 */
	public static List<List<String>> toolRequirements(String raw)
	{
		List<List<String>> out = new ArrayList<>();
		if (raw == null)
		{
			return out;
		}
		// Split on commas outside of wiki links, then clean each piece
		for (String part : splitTopLevel(raw))
		{
			if (OPTIONAL.matcher(part).find())
			{
				continue;
			}
			String cleaned = clean(part);
			if (cleaned == null || cleaned.isEmpty() || cleaned.equalsIgnoreCase("none"))
			{
				continue;
			}
			List<String> alts = new ArrayList<>();
			for (String alt : OR_SPLIT.split(cleaned))
			{
				String a = alt.trim();
				if (!a.isEmpty() && !a.equalsIgnoreCase("none"))
				{
					alts.add(a);
				}
			}
			if (!alts.isEmpty())
			{
				out.add(alts);
			}
		}
		return out;
	}

	private static List<String> splitTopLevel(String s)
	{
		List<String> parts = new ArrayList<>();
		int depth = 0;
		StringBuilder cur = new StringBuilder();
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			if (c == '[' || c == '{' || c == '<')
			{
				depth++;
			}
			else if ((c == ']' || c == '}' || c == '>') && depth > 0)
			{
				depth--;
			}
			if (c == ',' && depth == 0)
			{
				parts.add(cur.toString());
				cur.setLength(0);
			}
			else
			{
				cur.append(c);
			}
		}
		parts.add(cur.toString());
		return parts;
	}

	/** Escapes text for a single-quoted Lua string in a bucket query. */
	public static String lua(String s)
	{
		return s.replace("\\", "\\\\").replace("'", "\\'");
	}

	private static final java.util.regex.Pattern FIRST_LINK = java.util.regex.Pattern.compile("\\[\\[([^\\]|]+)(?:\\|[^\\]]*)?]]");

	/**
	 * The page a piece of wikitext links to: "[[Shop keeper (Varrock Swordshop)|Shop keeper]]" gives
	 * "Shop keeper (Varrock Swordshop)". Text without a link is just cleaned.
	 */
	public static String linkTarget(String s)
	{
		if (s == null)
		{
			return null;
		}
		java.util.regex.Matcher m = FIRST_LINK.matcher(s);
		while (m.find())
		{
			String target = m.group(1).trim();
			if (!target.regionMatches(true, 0, "File:", 0, 5))
			{
				return target;
			}
		}
		return clean(s);
	}
}

package com.materialplanner.recipes;

/**
 * OSRS experience table math.
 */
public final class Xp
{
	public static final int MAX_LEVEL = 99;
	private static final int[] TABLE = new int[MAX_LEVEL + 1];

	static
	{
		double points = 0;
		for (int lvl = 1; lvl <= MAX_LEVEL; lvl++)
		{
			TABLE[lvl] = (int) Math.floor(points / 4);
			points += Math.floor(lvl + 300 * Math.pow(2, lvl / 7.0));
		}
	}

	private Xp()
	{
	}

	/**
	 * XP needed to reach a level, e.g. 99 → 13,034,431.
	 */
	public static int forLevel(int level)
	{
		return TABLE[Math.max(1, Math.min(MAX_LEVEL, level))];
	}

	public static int levelFor(long xp)
	{
		for (int lvl = MAX_LEVEL; lvl > 1; lvl--)
		{
			if (xp >= TABLE[lvl])
			{
				return lvl;
			}
		}
		return 1;
	}

	/**
	 * Actions needed to go from {@code currentXp} to {@code targetLevel}, or 0 if already there.
	 */
	public static int actionsToLevel(long currentXp, int targetLevel, double xpPerAction)
	{
		if (xpPerAction <= 0)
		{
			return 0;
		}
		long needed = forLevel(targetLevel) - currentXp;
		if (needed <= 0)
		{
			return 0;
		}
		return (int) Math.ceil(needed / xpPerAction);
	}
}

package com.materialplanner.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.ImageIcon;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.http.api.item.ItemPrice;

/**
 * Item sprites by id, name → id lookup for materials the player doesn't own, and GE prices.
 */
class IconCache
{
	private final ItemManager itemManager;
	private final Map<Integer, ImageIcon> icons = new HashMap<>();
	private final Map<String, Integer> nameToId = new HashMap<>();

	IconCache(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * @param repaintTarget repainted once the sprite finishes loading
	 */
	ImageIcon get(int itemId, Component repaintTarget)
	{
		if (itemId <= 0)
		{
			return null;
		}
		return icons.computeIfAbsent(itemId, id ->
		{
			AsyncBufferedImage img = itemManager.getImage(id);
			if (repaintTarget != null)
			{
				img.onLoaded(repaintTarget::repaint);
			}
			return new ImageIcon(img);
		});
	}

	/**
	 * Exact-name lookup against the Grand Exchange item list. Untradeable items return -1.
	 */
	int idForName(String name)
	{
		String key = name.toLowerCase();
		return nameToId.computeIfAbsent(key, k ->
		{
			List<ItemPrice> results = itemManager.search(name);
			for (ItemPrice p : results)
			{
				if (p.getName().equalsIgnoreCase(name))
				{
					return p.getId();
				}
			}
			return -1;
		});
	}

	/**
	 * GE price each, or -1 for untradeable or unknown items.
	 */
	long price(String name)
	{
		if ("coins".equalsIgnoreCase(name))
		{
			return 1;
		}
		int id = idForName(name);
		if (id <= 0)
		{
			return -1;
		}
		long p = itemManager.getItemPrice(id);
		return p > 0 ? p : -1;
	}

	/**
	 * A small drawn "x" so the remove control doesn't depend on the font having a ✕ glyph.
	 */
	static ImageIcon removeIcon(Color color)
	{
		int s = 10;
		BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(color);
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawLine(1, 1, s - 2, s - 2);
		g.drawLine(s - 2, 1, 1, s - 2);
		g.dispose();
		return new ImageIcon(img);
	}
}

package com.materialplanner.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;

/**
 * Small vector icons, drawn rather than typed: the RuneScape fonts have no arrows, crosses or check marks.
 * Each draws centered in a {@code size}×{@code size} box at (x, y).
 */
final class Icons
{
	interface Painter
	{
		void paint(Graphics2D g, int x, int y, int size, Color color);
	}

	private Icons()
	{
	}

	private static BasicStroke stroke(float w)
	{
		return new BasicStroke(w, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	}

	static final Painter CHEVRON_DOWN = (g, x, y, s, c) ->
	{
		g.setColor(c);
		g.setStroke(stroke(1.6f));
		double cx = x + s / 2.0;
		double cy = y + s / 2.0;
		double w = s * 0.26;
		Path2D p = new Path2D.Double();
		p.moveTo(cx - w, cy - w / 2);
		p.lineTo(cx, cy + w / 2);
		p.lineTo(cx + w, cy - w / 2);
		g.draw(p);
	};

	static final Painter CHEVRON_RIGHT = (g, x, y, s, c) ->
	{
		g.setColor(c);
		g.setStroke(stroke(1.6f));
		double cx = x + s / 2.0;
		double cy = y + s / 2.0;
		double w = s * 0.26;
		Path2D p = new Path2D.Double();
		p.moveTo(cx - w / 2, cy - w);
		p.lineTo(cx + w / 2, cy);
		p.lineTo(cx - w / 2, cy + w);
		g.draw(p);
	};

	static final Painter CROSS = (g, x, y, s, c) ->
	{
		g.setColor(c);
		g.setStroke(stroke(1.6f));
		double m = s * 0.3;
		g.draw(new Line2D.Double(x + m, y + m, x + s - m, y + s - m));
		g.draw(new Line2D.Double(x + s - m, y + m, x + m, y + s - m));
	};

	static final Painter PLUS = (g, x, y, s, c) ->
	{
		g.setColor(c);
		g.setStroke(stroke(1.6f));
		double m = s * 0.28;
		g.draw(new Line2D.Double(x + m, y + s / 2.0, x + s - m, y + s / 2.0));
		g.draw(new Line2D.Double(x + s / 2.0, y + m, x + s / 2.0, y + s - m));
	};

	static final Painter MINUS = (g, x, y, s, c) ->
	{
		g.setColor(c);
		g.setStroke(stroke(1.6f));
		double m = s * 0.28;
		g.draw(new Line2D.Double(x + m, y + s / 2.0, x + s - m, y + s / 2.0));
	};

	static final Painter SEARCH = (g, x, y, s, c) ->
	{
		g.setColor(c);
		g.setStroke(stroke(1.5f));
		double r = s * 0.27;
		double cx = x + s * 0.44;
		double cy = y + s * 0.44;
		g.draw(new Ellipse2D.Double(cx - r, cy - r, r * 2, r * 2));
		g.draw(new Line2D.Double(cx + r * 0.72, cy + r * 0.72, x + s * 0.8, y + s * 0.8));
	};

	static final Painter REFRESH = (g, x, y, s, c) ->
	{
		g.setColor(c);
		g.setStroke(stroke(1.5f));
		double r = s * 0.28;
		double cx = x + s / 2.0;
		double cy = y + s / 2.0;
		g.draw(new java.awt.geom.Arc2D.Double(cx - r, cy - r, r * 2, r * 2, 60, 280, java.awt.geom.Arc2D.OPEN));
		// arrow head at the arc's start (60°)
		double ax = cx + r * Math.cos(Math.toRadians(60));
		double ay = cy - r * Math.sin(Math.toRadians(60));
		Path2D p = new Path2D.Double();
		p.moveTo(ax - s * 0.16, ay - s * 0.06);
		p.lineTo(ax, ay);
		p.lineTo(ax - s * 0.02, ay + s * 0.17);
		g.draw(p);
	};

	static final Painter CHECK = (g, x, y, s, c) ->
	{
		g.setColor(c);
		g.setStroke(stroke(1.7f));
		Path2D p = new Path2D.Double();
		p.moveTo(x + s * 0.24, y + s * 0.52);
		p.lineTo(x + s * 0.42, y + s * 0.7);
		p.lineTo(x + s * 0.76, y + s * 0.32);
		g.draw(p);
	};

	/** A filled dot, used as a status marker. */
	static final Painter DOT = (g, x, y, s, c) ->
	{
		g.setColor(c);
		double r = s * 0.22;
		g.fill(new Ellipse2D.Double(x + s / 2.0 - r, y + s / 2.0 - r, r * 2, r * 2));
	};
}

